function [tau] = radiation_torque(g, sb, p)
%RADIATION_TORQUE  The torque [N m] of light of pressure p arriving from the body direction sb (unit, towards the source) on the faces.
%   g: Facets (passed rec)
%   sb: real[1][3] (passed a plain number)
%   p: real[Pa] (passed in kg/(m s^2))
%   returns tau: real[N m][3] (passed in m^2 kg/s^2)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    tau = zeros(3, 1);
    tau = [0; 0; 0];
    for j = (0):((6) - 1)
        c = (sb(1)*g.n((j) + 1, 1) + sb(2)*g.n((j) + 1, 2) + sb(3)*g.n((j) + 1, 3));
        if (~(c <= 0))
            f = [0; 0; 0];
            k = ((0):((3) - 1)).';
            f((k) + 1) = ((((-(p)) * g.a((j) + 1)) * c) .* (((1 - g.rho_spec) .* reshape(sb((k) + 1), [], 1)) + ((2 * ((g.rho_spec * c) + (g.rho_diff / 3))) .* (g.n((j) + 1, (k) + 1)).')));
            tau = (tau + [g.rho((j) + 1, 2)*f(3) - g.rho((j) + 1, 3)*f(2); g.rho((j) + 1, 3)*f(1) - g.rho((j) + 1, 1)*f(3); g.rho((j) + 1, 1)*f(2) - g.rho((j) + 1, 2)*f(1)]);
        end
    end
end
